// ── source: vcx/platform/store_cxpack_fold_test.v ──
// store_cxpack_fold_test.v — #617 behavioral evidence that the #603 size-tiered
// segment fold runs OFF the flush turn without changing what a reader observes:
// a LOCKED store's folds land via the background worker and converge to the
// same logarithmic segment bound, everything reloads identically, and a fold
// plan overtaken by a compaction abandons cleanly (generation guard) instead of
// clobbering the fresh segment set.

fn cf_root(tag string) string {
	return os.join_path(os.temp_dir(), 'cxpack_fold_${tag}_${os.getpid()}')
}

fn cf_new(root string) &MemStore {
	return &MemStore{
		url:     'file://${root}'
		backend: 'cxpack'
		root:    root
		is_open: true
		op_lock: sync.new_mutex()
	}
}

fn cf_put(mut ms MemStore, text string) string {
	doc := cx.parse(text) or { panic('parse: ${text}') }
	c := render_canonical(doc.elements[0])
	h := cx.cx_text_hash(c) or { panic('hash') }
	store_lock_enter(mut ms)
	store_put_canonical(mut ms, h, c) or { panic('put: ' + err.msg()) }
	store_cxpack_flush(mut ms) or { panic('flush: ${err.msg()}') }
	store_lock_exit(mut ms)
	return h
}

// cf_quiesce waits (bounded) until no fold is running or pending — the async
// worker owns no completion signal by design (folding is amortization, not
// durability), so tests converge by polling under the lock.
fn cf_quiesce(mut ms MemStore) {
	for _ in 0 .. 2000 {
		store_lock_enter(mut ms)
		done := !ms.fold_running && !ms.obj_pack.fold_pending()
		store_lock_exit(mut ms)
		if done {
			return
		}
		time.sleep(5 * time.millisecond)
	}
	panic('background segment folds did not quiesce within the deadline')
}

fn cf_seg_files(root string) int {
	mut n := 0
	for e in os.ls(root) or { []string{} } {
		if cxpack_seg_index(e) >= 0 {
			n++
		}
	}
	return n
}

// A LOCKED store (the shape every opened store has) folds via the background
// worker: many appends still converge to a logarithmic segment-file count, the
// backend bookkeeping matches the disk, and every doc reloads byte-identically
// from the folded segments.
fn test_background_fold_converges_and_reloads() {
	root := cf_root('async')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms := cf_new(root)
	mut hashes := []string{}
	for i in 0 .. 3 * cxpack_compact_segments {
		hashes << cf_put(mut ms, '[rec [id ${i}] [v "val-${i}"]]')
	}
	cf_quiesce(mut ms)

	assert !os.exists(os.join_path(root, cxpack_pack)), 'append-only store must not pay the O(live) full compaction'
	segs := cf_seg_files(root)
	assert segs > 0 && segs < 8, 'background tier fold should bound ${3 * cxpack_compact_segments} appends to a few segment files (found ${segs})'
	store_lock_enter(mut ms)
	live := ms.obj_pack.live_segments()
	store_lock_exit(mut ms)
	assert live == segs, 'backend live-segment bookkeeping out of step with the files on disk'

	mut ms2 := cf_new(root)
	store_cxpack_load(mut ms2) or { panic('load: ' + err.msg()) }
	assert ms2.doc_order.len == hashes.len, 'doc count changed across background-fold reload'
	for i, h in hashes {
		assert (store_doc_text(ms2, h) or { '' }) == "[rec [id ${i}] [v 'val-${i}']]", 'doc ${h} wrong after background-fold reload'
	}
}

// A fold plan whose I/O was overtaken by a compaction must ABANDON at commit
// (generation guard): the merged temp is discarded, the fresh segment set is
// untouched, and the store reloads whole. Driven synchronously through the
// backend primitives so the race window is deterministic.
fn test_fold_commit_abandons_after_compaction_reset() {
	dir := cf_root('genabort')
	os.rmdir_all(dir) or {}
	defer {
		os.rmdir_all(dir) or {}
	}
	mut be := cxstore.open_pack_object_backend(dir)
	mut payloads := [][]u8{}
	// two same-size segments → a due fold
	for i in 0 .. 2 {
		p := 'fold-abort-payload-${i}'.bytes()
		payloads << p
		_ := be.put_object(p) or { panic('put: ${err}') }
		be.flush_segment() or { panic('flush: ${err}') }
	}
	plan := be.fold_plan() or { panic('a same-size segment pair must plan a fold') }
	merged := cxstore.fold_perform(plan) or { panic('perform: ${err}') }
	assert merged == 2

	// the compaction wins the race: generation bumps, segments are replaced
	be.write_compacted(payloads) or { panic('compact: ${err}') }
	committed := be.fold_commit(plan, merged) or { panic('commit: ${err}') }
	assert !committed, 'a fold planned under an older generation must abandon at commit'
	assert !os.exists(plan.tmp), 'an abandoned fold must discard its merged temp'
	assert be.live_segments() == 0, 'an abandoned fold must not touch the compacted segment set'

	mut be2 := cxstore.open_pack_object_backend(dir)
	objs := be2.load_objects() or { panic('reload: ${err}') }
	assert objs.len == 2, 'both objects must survive in the compacted pack (found ${objs.len})'
}

// The ratio guard (#617): a small tier stranded below a much larger newer one
// must NOT plan a fold — bare prev<=cur would license an O(big) rewrite for an
// O(1) gain on every batch (the measured async pathology). Folding proceeds
// normally ABOVE the stranded tier and converges without ever touching it.
fn test_fold_plan_skips_disproportionate_pair() {
	dir := cf_root('ratio')
	os.rmdir_all(dir) or {}
	defer {
		os.rmdir_all(dir) or {}
	}
	mut be := cxstore.open_pack_object_backend(dir)
	// sizes [1, 4]: prev <= cur but 1*2 < 4 — stranded, never folded.
	sizes := [1, 4]
	for si, n in sizes {
		for i in 0 .. n {
			_ := be.put_object('ratio-${si}-${i}'.bytes()) or { panic('put: ${err}') }
		}
		be.flush_segment() or { panic('flush: ${err}') }
	}
	assert !be.fold_pending(), 'a >2x disproportionate pair must not plan a fold'
	assert be.live_segments() == 2

	// appends above the stranded tier still tier normally: [1,4] + 3 + 3 →
	// (3,3) folds to 6, (4,6) folds to 10, (1,10) stays stranded.
	for si, n in [3, 3] {
		for i in 0 .. n {
			_ := be.put_object('ratio-above-${si}-${i}'.bytes()) or { panic('put: ${err}') }
		}
		be.flush_segment() or { panic('flush: ${err}') }
	}
	be.fold_drain() or { panic('drain: ${err}') }
	assert be.live_segments() == 2, 'tiers above a stranded segment must still fold (found ${be.live_segments()})'
	assert !be.fold_pending()
	assert be.object_count() == 11
}

// fold_drain (the lockless/inline driver) pairs by SIZE, not by position:
// the equal smalls fold first wherever they sit, and the merge then earns its
// fold with the bigger tier (2+2 → 4, then 4+4 within ratio) — converging to
// one segment with every object still resolvable.
fn test_fold_drain_pairs_by_size_and_converges() {
	dir := cf_root('bysize')
	os.rmdir_all(dir) or {}
	defer {
		os.rmdir_all(dir) or {}
	}
	mut be := cxstore.open_pack_object_backend(dir)
	mut keys := [][]u8{}
	sizes := [4, 1, 1]
	for si, n in sizes {
		for i in 0 .. n {
			k := be.put_object('bysize-${si}-${i}'.bytes()) or { panic('put: ${err}') }
			keys << k
		}
		be.flush_segment() or { panic('flush: ${err}') }
	}
	assert be.live_segments() == 3
	be.fold_drain() or { panic('drain: ${err}') }
	assert be.live_segments() == 1, 'size-paired drain must converge [4,1,1] → [2,4] → [6] (found ${be.live_segments()} segments)'
	assert !be.fold_pending()
	for k in keys {
		if _ := be.get_object(k) {
		} else {
			panic('object ${k.hex()} unresolvable after folds')
		}
	}
}

// ── source: vcx/platform/store_cxpack_incremental_test.v ──
// store_cxpack_incremental_test.v — #129-B behavioral evidence that cxpack://
// persists INCREMENTALLY: each mutation flushes only the delta (new objects to a
// fresh segment pack, new/removed manifest entries appended/tombstoned), the
// store reloads correctly across many segments, deletes survive a reload, and
// accumulated segments compact back into one pack — all without changing what a
// reader observes.

fn ci_canon_hash(text string) (string, string) {
	doc := cx.parse(text) or { return text, '' }
	c := render_canonical(doc.elements[0])
	h := cx.cx_text_hash(c) or { return c, '' }
	return c, h
}

fn ci_root(tag string) string {
	return os.join_path(os.temp_dir(), 'cxpack_inc_${tag}_${os.getpid()}')
}

fn ci_new(root string) &MemStore {
	return &MemStore{
		url:     'file://${root}'
		backend: 'cxpack'
		root:    root
		is_open: true
	}
}

// a put that mirrors the real mutation hook: stage into the live graph, then
// flush the delta (store_persist routes here for cxpack).
fn ci_put(mut ms MemStore, text string) string {
	c, h := ci_canon_hash(text)
	store_put_canonical(mut ms, h, c) or { panic('put: ' + err.msg()) }
	store_cxpack_flush(mut ms) or { panic('flush: ${err.msg()}') }
	return h
}

fn ci_seg_count(root string) int {
	mut n := 0
	for e in os.ls(root) or { []string{} } {
		if cxpack_seg_index(e) >= 0 {
			n++
		}
	}
	return n
}

// Each incremental put writes a separate segment, and a one-field-different doc's
// segment holds only the delta objects (structural sharing across flushes — the
// core O(delta) property the snapshot model lacked). Everything reloads.
fn test_incremental_segments_and_delta() {
	root := ci_root('delta')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	big := '[customer [name "Acme"] [addr [street "1 Main"] [city "NYC"] [zip "10001"]] [tags [t "a"] [t "b"] [t "c"]]]'
	mut ms := ci_new(root)
	h1 := ci_put(mut ms, '[order [id 1] ${big}]')
	assert ci_seg_count(root) == 1, 'first put should write one segment'
	seg0 := cxstore.open_pack(os.join_path(root, cxpack_seg_name(0))) or {
		panic('open seg0: ' + err.msg())
	}
	n0 := seg0.hashes().len

	h2 := ci_put(mut ms, '[order [id 2] ${big}]') // shares the whole `big` subtree
	assert ci_seg_count(root) == 2, 'second put should write a second segment'
	seg1 := cxstore.open_pack(os.join_path(root, cxpack_seg_name(1))) or {
		panic('open seg1: ' + err.msg())
	}
	n1 := seg1.hashes().len
	assert n1 > 0 && n1 < n0, 'delta segment (${n1}) must be smaller than the full first doc (${n0}) — shared subtree not re-stored'

	// reload across BOTH segments: both docs reconstruct byte-identically.
	mut ms2 := ci_new(root)
	store_cxpack_load(mut ms2) or { panic('load: ' + err.msg()) }
	assert ms2.doc_order == [h1, h2], 'order/contents changed across multi-segment reload'
	// reconstruct byte-identically to the live (pre-reload) canonical text.
	assert (store_doc_text(ms2, h1) or { '' }) == (store_doc_text(ms, h1) or { 'x' })
	assert (store_doc_text(ms2, h2) or { '' }) == (store_doc_text(ms, h2) or { 'x' })
}

// A deleted doc is tombstoned in the append-only manifest and is GONE after a
// reload, while the surviving docs remain intact (no whole-store rewrite needed).
fn test_incremental_delete_tombstone_survives_reload() {
	root := ci_root('del')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms := ci_new(root)
	h1 := ci_put(mut ms, '[a [x 1]]')
	h2 := ci_put(mut ms, '[b [y 2]]')
	h3 := ci_put(mut ms, '[c [z 3]]')

	store_delete_local(mut ms, h2)
	store_cxpack_flush(mut ms) or { panic('flush: ${err.msg()}') } // appends a 'T' tombstone

	mut ms2 := ci_new(root)
	store_cxpack_load(mut ms2) or { panic('load: ' + err.msg()) }
	assert ms2.doc_order == [h1, h3], 'deleted doc must not reappear after reload (got ${ms2.doc_order})'
	assert store_doc_present(ms2, h1)
	assert !store_doc_present(ms2, h2), 'tombstoned doc is data loss if it reloads'
	assert store_doc_present(ms2, h3)
}

// #603 scan-cursor alignment: deleting a doc BELOW the flush scan cursor shifts
// doc_order left — a doc put afterwards must still reach the manifest (a
// misaligned cursor would silently skip it: data loss on reload).
fn test_incremental_delete_below_cursor_then_put() {
	root := ci_root('cursor')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms := ci_new(root)
	h1 := ci_put(mut ms, '[a [x 1]]')
	h2 := ci_put(mut ms, '[b [y 2]]') // cursor now sits past both docs
	// delete below the cursor and stage a NEW doc before any flush: the put
	// lands at an index the stale cursor would already have covered.
	store_delete_local(mut ms, h1)
	c3, h3 := ci_canon_hash('[c [z 3]]')
	store_put_canonical(mut ms, h3, c3) or { panic('put: ' + err.msg()) }
	store_cxpack_flush(mut ms) or { panic('flush: ${err.msg()}') }

	mut ms2 := ci_new(root)
	store_cxpack_load(mut ms2) or { panic('load: ' + err.msg()) }
	assert ms2.doc_order == [h2, h3], 'doc put after a below-cursor delete must survive reload (got ${ms2.doc_order})'
	assert store_doc_present(ms2, h3), 'post-delete put lost — scan cursor misaligned'
}

// Alias set / update / delete are all carried incrementally (A records +
// last-write-wins, X tombstone) and reload to the final live state.
fn test_incremental_alias_lifecycle() {
	root := ci_root('alias')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms := ci_new(root)
	h1 := ci_put(mut ms, '[a [x 1]]')
	h2 := ci_put(mut ms, '[b [y 2]]')

	// set, then update, then a second alias, then delete the first — through the
	// #603 mutation seam (direct map pokes bypass the O(delta) flush discovery).
	store_alias_set_local(mut ms, 'latest', h1)
	store_cxpack_flush(mut ms) or { panic('flush: ${err.msg()}') }
	store_alias_set_local(mut ms, 'latest', h2) // update → new 'A' record (last-write-wins)
	store_cxpack_flush(mut ms) or { panic('flush: ${err.msg()}') }
	store_alias_set_local(mut ms, 'pinned', h1)
	store_cxpack_flush(mut ms) or { panic('flush: ${err.msg()}') }
	assert store_alias_delete_local(mut ms, 'pinned')
	store_cxpack_flush(mut ms) or { panic('flush: ${err.msg()}') }

	mut ms2 := ci_new(root)
	store_cxpack_load(mut ms2) or { panic('load: ' + err.msg()) }
	assert ms2.aliases['latest'] == h2, 'alias update lost across reload'
	assert 'pinned' !in ms2.aliases, 'deleted alias must not reload'
	assert ms2.alias_order == ['latest'], 'alias order wrong after reload (${ms2.alias_order})'
}

// #603: garbage-free appends never trip the O(live) full compaction — the
// size-tiered segment fold (binary counter over segment sizes) keeps the live
// segment-file count logarithmic instead, and everything reloads identically
// from the folded segments.
fn test_incremental_append_only_tiers_segments_no_full_compaction() {
	root := ci_root('compact')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms := ci_new(root)
	mut hashes := []string{}
	// well past the old every-16-segments threshold: 3× worth of appends.
	for i in 0 .. 3 * cxpack_compact_segments {
		hashes << ci_put(mut ms, '[rec [id ${i}] [v "val-${i}"]]')
	}
	// no garbage → no full compaction: the single store.cxpack never appears...
	assert !os.exists(os.join_path(root, cxpack_pack)), 'append-only store must not pay the O(live) full compaction'
	// ...and tiered folding keeps the segment-file count far below one-per-append.
	segs := ci_seg_count(root)
	assert segs > 0 && segs < 8, 'size-tiered fold should bound ${3 * cxpack_compact_segments} appends to a few segment files (found ${segs})'
	assert ms.obj_pack.live_segments() == segs, 'backend live-segment bookkeeping out of step with the files on disk'

	mut ms2 := ci_new(root)
	store_cxpack_load(mut ms2) or { panic('load: ' + err.msg()) }
	assert ms2.doc_order.len == hashes.len, 'doc count changed across tiered-fold reload'
	for i, h in hashes {
		// canonical renders quoted scalars with single quotes.
		assert (store_doc_text(ms2, h) or { '' }) == "[rec [id ${i}] [v 'val-${i}']]", 'doc ${h} wrong after tiered-fold reload'
	}
}

// Compaction reclaims objects no longer reachable from any live doc (GC): after
// deleting a doc whose subtree is unique, a compaction drops its objects.
fn test_compaction_reclaims_unreferenced_objects() {
	root := ci_root('gc')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms := ci_new(root)
	keep := ci_put(mut ms, '[keep [k 1]]')
	doomed := ci_put(mut ms,
		'[doomed [big "a-unique-subtree-not-shared-with-keep"] [more [deep "x"]]]')
	store_delete_local(mut ms, doomed)
	store_cxpack_flush(mut ms) or { panic('flush: ${err.msg()}') }

	before := ms.obj_sink.objects.len
	store_cxpack_compact(mut ms) or { panic('compact: ${err.msg()}') }
	after := ms.obj_sink.objects.len
	assert after < before, 'compaction must reclaim the deleted doc objects (before ${before}, after ${after})'

	// the kept doc still reloads; the doomed one stays gone.
	mut ms2 := ci_new(root)
	store_cxpack_load(mut ms2) or { panic('load: ' + err.msg()) }
	assert store_doc_present(ms2, keep)
	assert !store_doc_present(ms2, doomed)
	assert (store_doc_text(ms2, keep) or { '' }) == '[keep [k 1]]'
}

// ── source: vcx/platform/store_cxpack_subtree_test.v ──
// store_cxpack_subtree_test.v — #129 store-level behavioral evidence that the
// cxpack:// backend now persists via the subtree object graph: docs round-trip
// across persist/reload, identical subtrees dedup across documents, and a new
// version of a doc reuses the untouched subtree objects (structural sharing).

fn canon_and_hash(text string) (string, string) {
	doc := cx.parse(text) or { return text, '' }
	c := render_canonical(doc.elements[0])
	h := cx.cx_text_hash(c) or { return c, '' }
	return c, h
}

fn build_cxpack(root string, texts []string) &MemStore {
	mut ms := &MemStore{
		url:     'file://${root}'
		backend: 'cxpack'
		root:    root
		is_open: true
	}
	for t in texts {
		c, h := canon_and_hash(t)
		if h != '' {
			// #129-A: populate the LIVE object graph (not the docs map).
			store_put_canonical(mut ms, h, c) or { panic('put: ' + err.msg()) }
		}
	}
	return ms
}

fn pack_object_count(root string) int {
	r := cxstore.open_pack(os.join_path(root, cxpack_pack)) or { return -1 }
	return r.hashes().len
}

fn tmp_root(tag string) string {
	return os.join_path(os.temp_dir(), 'cxpack_${tag}_${os.getpid()}')
}

// (correctness) docs persisted as an object graph reload byte-identically.
fn test_cxpack_subtree_roundtrip() {
	root := tmp_root('rt')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	texts := [
		'[order [id 1] [customer [name "Acme"] [addr [city "NYC"]]]]',
		'[order [id 2] [customer [name "Acme"] [addr [city "NYC"]]]]',
	]
	mut ms := build_cxpack(root, texts)
	store_cxpack_compact(mut ms) or { panic('compact: ${err.msg()}') }
	mut ms2 := &MemStore{
		backend: 'cxpack'
		root:    root
		is_open: true
	}
	store_cxpack_load(mut ms2) or { panic('load: ' + err.msg()) }
	assert ms2.doc_order.len == ms.doc_order.len, 'doc count changed across reload'
	for h in ms.doc_order {
		assert store_doc_present(ms2, h), 'doc ${h} missing after reload'
		got := store_doc_text(ms2, h) or { panic('reconstruct ${h}: ' + err.msg()) }
		want := store_doc_text(ms, h) or { panic('reconstruct src ${h}: ' + err.msg()) }
		assert got == want, 'doc ${h} canonical text changed across reload'
	}
}

// (#129-A) dedup + structural sharing are LIVE in the in-memory object sink —
// before any persistence. Two docs sharing a subtree share objects in the live
// store, and a one-field modify adds only the changed path.
fn test_objgraph_live_in_memory_sharing() {
	mut ms := &MemStore{
		backend: 'mem-objgraph-probe'
		is_open: true
	}
	// force the object-graph path for this probe regardless of backend name
	ms.backend = 'cxpack'
	big := '[customer [name "Acme"] [addr [street "1 Main"] [city "NYC"]] [tags [t "a"] [t "b"] [t "c"]]]'
	c1, h1 := canon_and_hash('[order [id 1] ${big}]')
	c2, h2 := canon_and_hash('[order [id 2] ${big}]')
	store_put_canonical(mut ms, h1, c1) or { panic(err.msg()) }
	after1 := ms.obj_sink.objects.len
	store_put_canonical(mut ms, h2, c2) or { panic(err.msg()) }
	after2 := ms.obj_sink.objects.len
	// the second doc shares the `big` subtree → adds far fewer objects than the first
	added := after2 - after1
	assert added > 0 && added < after1, 'expected live sharing: doc1 added ${after1}, doc2 added only ${added}'
	// both docs are readable from the live graph (no persistence happened)
	assert (store_doc_text(ms, h1) or { '' }) == c1, 'doc1 not live-reconstructable'
	assert (store_doc_text(ms, h2) or { '' }) == c2, 'doc2 not live-reconstructable'
}

// (cross-doc dedup) two docs sharing a subtree store fewer objects than two docs
// that share nothing.
fn test_cxpack_cross_doc_dedup() {
	big := '[customer [name "Acme"] [addr [street "1 Main"] [city "NYC"] [zip "10001"]] [contacts [c "a@x"] [c "b@x"] [c "d@x"]]]'
	big2 := '[supplier [name "Globex"] [addr [street "9 Oak"] [city "LA"] [zip "90001"]] [contacts [c "p@y"] [c "q@y"] [c "r@y"]]]'
	shared_texts := ['[order [id 1] ${big}]', '[order [id 2] ${big}]']
	disjoint_texts := ['[order [id 1] ${big}]', '[order [id 2] ${big2}]']

	rs := tmp_root('shared')
	rd := tmp_root('disjoint')
	os.rmdir_all(rs) or {}
	os.rmdir_all(rd) or {}
	defer {
		os.rmdir_all(rs) or {}
		os.rmdir_all(rd) or {}
	}
	mut ms_s := build_cxpack(rs, shared_texts)
	store_cxpack_compact(mut ms_s) or { panic('compact: ${err.msg()}') }
	mut ms_d := build_cxpack(rd, disjoint_texts)
	store_cxpack_compact(mut ms_d) or { panic('compact: ${err.msg()}') }
	ns := pack_object_count(rs)
	nd := pack_object_count(rd)
	assert ns > 0 && nd > 0, 'pack object count unavailable (${ns}, ${nd})'
	assert ns < nd, 'expected shared-subtree pack (${ns} objs) to be smaller than disjoint (${nd} objs)'
}

// (version sharing) a one-field new version of a doc adds far fewer objects than
// the whole doc — untouched subtrees are reused, not rewritten.
fn test_cxpack_modify_version_sharing() {
	big := '[body [a "1"] [b "2"] [c "3"] [d "4"] [e "5"] [f "6"] [g "7"] [h "8"]]'
	v1 := '[doc ${big} [v "ORIGINAL"]]'
	v2 := '[doc ${big} [v "CHANGED"]]'

	r1 := tmp_root('v1')
	r12 := tmp_root('v12')
	os.rmdir_all(r1) or {}
	os.rmdir_all(r12) or {}
	defer {
		os.rmdir_all(r1) or {}
		os.rmdir_all(r12) or {}
	}
	mut ms_1 := build_cxpack(r1, [v1])
	store_cxpack_compact(mut ms_1) or { panic('compact: ${err.msg()}') }
	mut ms_12 := build_cxpack(r12, [v1, v2])
	store_cxpack_compact(mut ms_12) or { panic('compact: ${err.msg()}') }
	n1 := pack_object_count(r1)
	n12 := pack_object_count(r12)
	added := n12 - n1
	assert n1 > 0 && added > 0, 'unexpected object counts (n1=${n1}, added=${added})'
	assert added < n1, 'a one-field new version should add fewer objects (${added}) than a full doc has (${n1})'
}

// (#129-C integrity) corruption on load is a HARD ERROR, never a silent drop.
// A manifest entry pointing at an object absent from the pack must fail the load
// — a silently-dropped doc would be data loss masquerading as success.
fn test_cxpack_load_corruption_is_hard_error() {
	root := tmp_root('corrupt')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	// a valid store on disk first
	mut ms0 := build_cxpack(root, ['[doc [x 1]]'])
	store_cxpack_compact(mut ms0) or { panic('compact: ${err.msg()}') }
	assert os.exists(os.join_path(root, cxpack_pack)), 'precondition: pack written'

	// corrupt the manifest: a doc whose object root is absent from the pack
	missing := '0'.repeat(64)
	os.write_file(os.join_path(root, cxpack_manifest), 'D\tdeadbeefdoc\t${missing}\n') or {
		assert false, 'could not rewrite manifest'
		return
	}
	mut ms := &MemStore{
		backend: 'cxpack'
		root:    root
		is_open: true
	}
	store_cxpack_load(mut ms) or {
		// expected: integrity error, and NO doc silently loaded
		assert ms.doc_order.len == 0, 'corrupt doc must not be partially loaded'
		return
	}
	assert false, 'expected a hard integrity error on a missing-object manifest entry; load silently succeeded (data-loss regression)'
}

// (#129-C) a manifest present without its pack is incomplete → hard error.
fn test_cxpack_incomplete_store_is_hard_error() {
	root := tmp_root('incomplete')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms0 := build_cxpack(root, ['[doc [y 2]]'])
	store_cxpack_compact(mut ms0) or { panic('compact: ${err.msg()}') }
	os.rm(os.join_path(root, cxpack_pack)) or {
		assert false, 'could not remove pack'
		return
	}
	mut ms := &MemStore{
		backend: 'cxpack'
		root:    root
		is_open: true
	}
	store_cxpack_load(mut ms) or { return } // expected error
	assert false, 'expected a hard error when the pack is missing but the manifest is present'
}

// ── source: vcx/platform/store_encryption_test.v ──
// store_encryption_test.v — #114 (PR-E) encryption-at-rest INTEGRATION through the
// store object-graph: a cxobj:// store opened with `encrypt-key-id` decomposes a
// doc into the subtree object graph and AEAD-seals each object at rest (envelope:
// per-object DEK wrapped by the env-resolved KEK). The object graph keys by the
// PLAINTEXT hash, so dedup/structural-sharing are unchanged; only the bytes on disk
// are ciphertext. Proves: round-trip reconstruct, NO plaintext at rest, and
// fail-closed on a wrong KEK. (The AEAD primitive + KMS seam are unit-tested in
// vcx/cxstore/encryption_test.v; this is the live store integration.)

const enc_test_kek = '00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff'

fn enc_canon_hash(text string) (string, string) {
	c := render_canonical(cx.parse(text) or { panic('parse: ${err.msg()}') }.elements[0])
	h := cx.cx_text_hash(c) or { panic('hash: ${err.msg()}') }
	return c, h
}

fn enc_dir_has_plaintext(objdir string, needles []string) bool {
	shards := os.ls(objdir) or { return false }
	for sh in shards {
		sub := os.join_path(objdir, sh)
		if !os.is_dir(sub) {
			continue
		}
		for f in (os.ls(sub) or { []string{} }) {
			blob := os.read_bytes(os.join_path(sub, f)) or { continue }
			s := blob.bytestr()
			for n in needles {
				if s.contains(n) {
					return true
				}
			}
		}
	}
	return false
}

fn enc_cxobj_load_ok(mut ms MemStore) bool {
	store_cxobj_load(mut ms) or { return false }
	return true
}

fn test_store_cxobj_encrypted_roundtrip_and_at_rest() {
	dir := os.join_path(os.temp_dir(), 'cx_store_enc_${os.getpid()}')
	os.rmdir_all(dir) or {}
	defer {
		os.rmdir_all(dir) or {}
	}
	os.setenv('CX_STORE_KEK_tenant1', enc_test_kek, true)

	c, h := enc_canon_hash('[order [id 1] [customer [name "Acme"] [addr [city "NYC"]]]]')

	mut ms := &MemStore{
		url:        'file://${dir}?encoding=object-per-key'
		backend:    'cxobj'
		root:       dir
		is_open:    true
		enc_key_id: 'tenant1'
	}
	store_put_canonical(mut ms, h, c) or { panic('put: ${err.msg()}') }
	store_cxobj_flush(mut ms) or { panic('flush: ${err.msg()}') }

	// at rest: the object files must be ciphertext — no plaintext field values.
	objdir := os.join_path(dir, cxobj_objects_dir)
	assert os.exists(objdir), 'objects dir not written'
	assert !enc_dir_has_plaintext(objdir, ['Acme', 'NYC', 'customer']), 'plaintext must not appear at rest'

	// reopen with the SAME KEK → reconstruct byte-identical (lazy resolve + decrypt).
	mut ms2 := &MemStore{
		url:        'file://${dir}?encoding=object-per-key'
		backend:    'cxobj'
		root:       dir
		is_open:    true
		enc_key_id: 'tenant1'
	}
	assert enc_cxobj_load_ok(mut ms2), 'reopen with correct KEK must succeed'
	assert store_doc_present(ms2, h), 'doc missing after reopen'
	got := store_doc_text(ms2, h) or { panic('get: ${err.msg()}') }
	assert got == c, 'decrypted reconstruct must be byte-identical'

	os.unsetenv('CX_STORE_KEK_tenant1')
}

fn test_store_cxobj_encrypted_wrong_kek_fails_closed() {
	dir := os.join_path(os.temp_dir(), 'cx_store_enc_wk_${os.getpid()}')
	os.rmdir_all(dir) or {}
	defer {
		os.rmdir_all(dir) or {}
	}
	os.setenv('CX_STORE_KEK_tenant1', enc_test_kek, true)
	c, h := enc_canon_hash('[secret [token "hunter2"] [scope "admin"]]')
	mut ms := &MemStore{
		url:        'file://${dir}?encoding=object-per-key'
		backend:    'cxobj'
		root:       dir
		is_open:    true
		enc_key_id: 'tenant1'
	}
	store_put_canonical(mut ms, h, c) or { panic('put: ${err.msg()}') }
	store_cxobj_flush(mut ms) or { panic('flush: ${err.msg()}') }

	// reopen with a DIFFERENT KEK → the at-rest envelopes do not authenticate, so
	// objects resolve to none → reconstruction fails (never a silent wrong doc).
	os.setenv('CX_STORE_KEK_tenant1', 'ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff',
		true)
	mut ms2 := &MemStore{
		url:        'file://${dir}?encoding=object-per-key'
		backend:    'cxobj'
		root:       dir
		is_open:    true
		enc_key_id: 'tenant1'
	}
	enc_cxobj_load_ok(mut ms2) // load may register refs regardless; the get must fail
	recovered := store_doc_text(ms2, h) or { '' }
	assert recovered != c, 'wrong KEK must NOT reconstruct the plaintext (fail-closed)'

	// absent KEK → hard open error (fail-closed, no silent ephemeral key).
	os.unsetenv('CX_STORE_KEK_tenant1')
	mut ms3 := &MemStore{
		url:        'file://${dir}?encoding=object-per-key'
		backend:    'cxobj'
		root:       dir
		is_open:    true
		enc_key_id: 'tenant1'
	}
	assert !enc_cxobj_load_ok(mut ms3), 'absent KEK must fail to open the encrypted store'
}

// ── source: vcx/platform/store_pack_encryption_test.v ──
// store_pack_encryption_test.v — #229 encryption-at-rest INTEGRATION for the PACK
// substrate: a cxpack (bare `file://`) store opened with `encrypt-key-id`
// decomposes docs into the subtree object graph and stages each object through
// the EncryptingWrapper as an AEAD envelope keyed by the PLAINTEXT hash, flushed
// into v2 KEYED packs. Dedup/structural sharing are unchanged; only the at-rest
// bytes are ciphertext. Proves: round-trip reconstruct, NO plaintext at rest
// (segments AND the compacted pack), dedup parity with a plaintext store,
// fail-closed on wrong/absent KEK, and the keyed↔plaintext mode-mismatch guards.
// (The keyed pack format + wrapper are unit-tested in
// vcx/cxstore/encryption_wrapper_test.v; this is the live store integration.)

const penc_test_kek = '00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff'

fn penc_canon_hash(text string) (string, string) {
	c := render_canonical(cx.parse(text) or { panic('parse: ${err.msg()}') }.elements[0])
	h := cx.cx_text_hash(c) or { panic('hash: ${err.msg()}') }
	return c, h
}

// penc_dir_has_plaintext scans every pack file under `root` for the needles.
fn penc_dir_has_plaintext(root string, needles []string) bool {
	for f in (os.ls(root) or { []string{} }) {
		if !f.ends_with('.cxpack') {
			continue
		}
		blob := os.read_bytes(os.join_path(root, f)) or { continue }
		s := blob.bytestr()
		for n in needles {
			if s.contains(n) {
				return true
			}
		}
	}
	return false
}

fn penc_mem_store(dir string, key_id string) &MemStore {
	return &MemStore{
		url:        'file://${dir}'
		backend:    'cxpack'
		root:       dir
		is_open:    true
		enc_key_id: key_id
	}
}

fn penc_load_ok(mut ms MemStore) bool {
	store_cxpack_load(mut ms) or { return false }
	return true
}

fn penc_set_alias(mut ms MemStore, name string, hash string) {
	// #603: route through the mutation seam so the incremental flush sees it
	store_alias_set_local(mut ms, name, hash)
}

fn test_store_cxpack_encrypted_roundtrip_and_at_rest() {
	dir := os.join_path(os.temp_dir(), 'cx_store_penc_${os.getpid()}')
	os.rmdir_all(dir) or {}
	defer {
		os.rmdir_all(dir) or {}
	}
	os.setenv('CX_STORE_KEK_tenant1', penc_test_kek, true)
	defer {
		os.unsetenv('CX_STORE_KEK_tenant1')
	}

	c, h := penc_canon_hash('[order [id 1] [customer [name "Acme"] [addr [city "NYC"]]]]')

	mut ms := penc_mem_store(dir, 'tenant1')
	store_put_canonical(mut ms, h, c) or { panic('put: ${err.msg()}') }
	store_cxpack_flush(mut ms) or { panic('flush: ${err.msg()}') }
	penc_set_alias(mut ms, 'orders/latest', h)
	store_cxpack_flush(mut ms) or { panic('flush2: ${err.msg()}') }

	// at rest: pack files must be ciphertext — no plaintext field values, and no
	// plaintext alias name either (alias-name objects are sealed too).
	assert penc_dir_has_plaintext(dir, ['Acme', 'NYC', 'customer', 'orders/latest']) == false, 'plaintext must not appear in any pack at rest'

	// reopen with the SAME KEK → byte-identical reconstruct + alias resolves.
	mut ms2 := penc_mem_store(dir, 'tenant1')
	assert penc_load_ok(mut ms2), 'reopen with correct KEK must succeed'
	assert store_doc_present(ms2, h), 'doc missing after reopen'
	got := store_doc_text(ms2, h) or { panic('get: ${err.msg()}') }
	assert got == c, 'decrypted reconstruct must be byte-identical'
	assert ms2.aliases['orders/latest'] == h, 'alias must survive the encrypted round-trip'
}

fn test_store_cxpack_encrypted_dedup_parity() {
	// The object graph keys by PLAINTEXT hash, so an encrypted store must hold
	// EXACTLY as many distinct objects as a plaintext store of the same corpus
	// (structural sharing unchanged by encryption).
	dir_e := os.join_path(os.temp_dir(), 'cx_store_penc_dedup_e_${os.getpid()}')
	dir_p := os.join_path(os.temp_dir(), 'cx_store_penc_dedup_p_${os.getpid()}')
	os.rmdir_all(dir_e) or {}
	os.rmdir_all(dir_p) or {}
	defer {
		os.rmdir_all(dir_e) or {}
		os.rmdir_all(dir_p) or {}
	}
	os.setenv('CX_STORE_KEK_tenant1', penc_test_kek, true)
	defer {
		os.unsetenv('CX_STORE_KEK_tenant1')
	}

	// two docs sharing a large identical subtree
	c1, h1 := penc_canon_hash('[a [shared [x 1] [y 2] [z [deep "value"]]] [only "one"]]')
	c2, h2 := penc_canon_hash('[b [shared [x 1] [y 2] [z [deep "value"]]] [only "two"]]')

	mut mse := penc_mem_store(dir_e, 'tenant1')
	store_put_canonical(mut mse, h1, c1) or { panic(err) }
	store_put_canonical(mut mse, h2, c2) or { panic(err) }
	store_cxpack_flush(mut mse) or { panic(err) }

	mut msp := penc_mem_store(dir_p, '')
	store_put_canonical(mut msp, h1, c1) or { panic(err) }
	store_put_canonical(mut msp, h2, c2) or { panic(err) }
	store_cxpack_flush(mut msp) or { panic(err) }

	assert mse.obj_pack.object_count() == msp.obj_pack.object_count(), 'encrypted store must dedup exactly like plaintext (same distinct-object count)'
}

fn test_store_cxpack_encrypted_compaction() {
	dir := os.join_path(os.temp_dir(), 'cx_store_penc_comp_${os.getpid()}')
	os.rmdir_all(dir) or {}
	defer {
		os.rmdir_all(dir) or {}
	}
	os.setenv('CX_STORE_KEK_tenant1', penc_test_kek, true)
	defer {
		os.unsetenv('CX_STORE_KEK_tenant1')
	}

	mut ms := penc_mem_store(dir, 'tenant1')
	mut hashes := []string{}
	mut texts := []string{}
	for i in 0 .. 5 {
		c, h := penc_canon_hash('[doc [n ${i}] [secretfield "classified-${i}"]]')
		store_put_canonical(mut ms, h, c) or { panic(err) }
		store_cxpack_flush(mut ms) or { panic(err) }
		hashes << h
		texts << c
	}
	penc_set_alias(mut ms, 'compact/alias', hashes[0])
	store_cxpack_flush(mut ms) or { panic(err) }
	// fold everything (envelope-level compaction — never decrypts)
	store_cxpack_compact(mut ms) or { panic('compact: ${err.msg()}') }

	assert os.exists(os.join_path(dir, 'store.cxpack')), 'compacted pack must exist'
	assert penc_dir_has_plaintext(dir, ['classified-0', 'classified-4', 'secretfield',
		'compact/alias']) == false, 'compacted pack must stay ciphertext'

	// reopen: every doc reconstructs byte-identical from the compacted pack
	mut ms2 := penc_mem_store(dir, 'tenant1')
	assert penc_load_ok(mut ms2), 'reopen after compaction must succeed'
	for i, h in hashes {
		got := store_doc_text(ms2, h) or { panic('get ${i}: ${err.msg()}') }
		assert got == texts[i], 'doc ${i} must survive compaction byte-identical'
	}
	assert ms2.aliases['compact/alias'] == hashes[0]
}

fn test_store_cxpack_encrypted_wrong_or_absent_kek_fails_closed() {
	dir := os.join_path(os.temp_dir(), 'cx_store_penc_wk_${os.getpid()}')
	os.rmdir_all(dir) or {}
	defer {
		os.rmdir_all(dir) or {}
	}
	os.setenv('CX_STORE_KEK_tenant1', penc_test_kek, true)
	c, h := penc_canon_hash('[secret [token "hunter2"] [scope "admin"]]')
	mut ms := penc_mem_store(dir, 'tenant1')
	store_put_canonical(mut ms, h, c) or { panic(err) }
	store_cxpack_flush(mut ms) or { panic(err) }

	// wrong KEK → envelopes do not authenticate → HARD open error (the pack
	// load path decrypts eagerly, so this fails at open, never a wrong doc).
	os.setenv('CX_STORE_KEK_tenant1', 'ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff',
		true)
	mut ms2 := penc_mem_store(dir, 'tenant1')
	assert !penc_load_ok(mut ms2), 'wrong KEK must fail the open (fail-closed)'

	// absent KEK → hard open error (no silent ephemeral key).
	os.unsetenv('CX_STORE_KEK_tenant1')
	mut ms3 := penc_mem_store(dir, 'tenant1')
	assert !penc_load_ok(mut ms3), 'absent KEK must fail to open the encrypted store'
}

fn test_store_cxpack_mode_mismatch_fails_closed() {
	os.setenv('CX_STORE_KEK_tenant1', penc_test_kek, true)
	defer {
		os.unsetenv('CX_STORE_KEK_tenant1')
	}

	// encrypted store reopened WITHOUT encrypt-key-id → hard error, never
	// silently-empty / integrity-corrupt.
	dir_e := os.join_path(os.temp_dir(), 'cx_store_penc_mm_e_${os.getpid()}')
	os.rmdir_all(dir_e) or {}
	defer {
		os.rmdir_all(dir_e) or {}
	}
	c, h := penc_canon_hash('[doc [v 1]]')
	mut mse := penc_mem_store(dir_e, 'tenant1')
	store_put_canonical(mut mse, h, c) or { panic(err) }
	store_cxpack_flush(mut mse) or { panic(err) }
	mut plain_reopen := penc_mem_store(dir_e, '')
	assert !penc_load_ok(mut plain_reopen), 'encrypted store opened without its key must error'

	// plaintext store reopened WITH encrypt-key-id → hard error (encryption
	// cannot be enabled on existing data in place — that would mix modes).
	dir_p := os.join_path(os.temp_dir(), 'cx_store_penc_mm_p_${os.getpid()}')
	os.rmdir_all(dir_p) or {}
	defer {
		os.rmdir_all(dir_p) or {}
	}
	mut msp := penc_mem_store(dir_p, '')
	store_put_canonical(mut msp, h, c) or { panic(err) }
	store_cxpack_flush(mut msp) or { panic(err) }
	mut enc_reopen := penc_mem_store(dir_p, 'tenant1')
	assert !penc_load_ok(mut enc_reopen), 'encrypt-key-id on an existing plaintext store must error'
}

fn test_store_open_impl_encrypt_guard_matrix() {
	os.setenv('CX_STORE_KEK_tenant1', penc_test_kek, true)
	defer {
		os.unsetenv('CX_STORE_KEK_tenant1')
	}
	caps_set_all()
	mut auth := map[string]string{}
	auth['encrypt-key-id'] = 'tenant1'

	// mem:// cannot seal at rest → CXER1100 fail-closed (unchanged, #184).
	r_mem := store_open_impl('mem://enc-guard', '', '', false, true, auth.clone())
	assert node_err_code(r_mem) == 'cx-err:CXER1100', 'mem:// with encrypt-key-id must fail closed'

	// document model has no object graph → CXER1100 fail-closed.
	dir_d := os.join_path(os.temp_dir(), 'cx_store_penc_open_d_${os.getpid()}')
	os.rmdir_all(dir_d) or {}
	defer {
		os.rmdir_all(dir_d) or {}
	}
	r_doc := store_open_impl('document+file://${dir_d}', '', '', false, true, auth.clone())
	assert node_err_code(r_doc) == 'cx-err:CXER1100', 'document model with encrypt-key-id must fail closed'

	// bare file:// (pack, the default) now SEALS (#229): open must succeed and
	// write ciphertext-only packs through the full store surface.
	dir_k := os.join_path(os.temp_dir(), 'cx_store_penc_open_k_${os.getpid()}')
	os.rmdir_all(dir_k) or {}
	defer {
		os.rmdir_all(dir_k) or {}
	}
	r_pack := store_open_impl('file://${dir_k}', '', '', false, true, auth.clone())
	assert node_err_code(r_pack) == '', 'pack store with encrypt-key-id must open (got ${node_err_code(r_pack)})'
	sid := store_handle_id(r_pack) or { panic('no handle id') }
	mut ms := store_lookup(sid) or { panic('handle ${sid} not registered') }
	cc, hh := penc_canon_hash('[wired [via "store_open_impl"] [secretmark "open-path-classified"]]')
	store_put_canonical(mut ms, hh, cc) or { panic(err) }
	store_persist(mut ms) or { panic('persist: ${err.msg()}') }
	assert penc_dir_has_plaintext(dir_k, ['open-path-classified', 'secretmark']) == false, 'open-path writes must be sealed at rest'
}

// ── tiny node helpers (shared shape with other store tests) ──────────────────

fn node_err_code(n cx.Node) string {
	if n is cx.Element {
		for a in n.attrs {
			if a.name == 'code' {
				return cx.scalar_value_str_public(a.value)
			}
		}
	}
	return ''
}

fn store_handle_id(n cx.Node) ?int {
	if n is cx.Element {
		for a in n.attrs {
			if a.name == 'handle' {
				return cx.scalar_value_str_public(a.value).int()
			}
		}
	}
	return none
}

// ── source: vcx/platform/store_erase_test.v ──
// store_erase_test.v — W5 doc-level erasure substrate (I5 stream 4;
// spec/03-approved/xap/xsp_store_profile.md §7b.1, erasure_compliance.md §6):
// store_erase_doc_local destroys the doc entry AND records the attributed
// [erased …] tombstone in ONE act; the tombstone survives restart AND
// compaction (attribution always survives); a later re-put of the same
// content SUPERSEDES the tombstone (the T-record re-put precedent); erasing
// an absent doc still records the tombstone (replica convergence: erased,
// never not-found); re-erase is deduped (idempotent — never a second
// destructive act); the lineage records the act as kind=erase (the feed's
// shred-propagation carriage AND the store:log row ride the same log).

fn se_root(tag string) string {
	return os.join_path(os.temp_dir(), 'cx_store_erase_${tag}_${os.getpid()}')
}

fn se_new(root string) &MemStore {
	return &MemStore{
		url:     'file://${root}'
		backend: 'cxpack'
		root:    root
		is_open: true
	}
}

fn se_put(mut ms MemStore, text string) string {
	doc := cx.parse(text) or { panic('parse: ${text}') }
	c := render_canonical(doc.elements[0])
	h := cx.cx_text_hash(c) or { panic('hash') }
	store_put_canonical(mut ms, h, c) or { panic('put: ' + err.msg()) }
	store_cxpack_flush(mut ms) or { panic('flush: ${err.msg()}') }
	return h
}

fn se_erase(mut ms MemStore, hash string) string {
	mut root := []u8{}
	if r := ms.obj_roots[hash] {
		root = r.clone()
	}
	tomb := store_erase_tombstone(hash, root, '2026-08-07T12:00:00Z', 'did:key:tester',
		'gdpr-17', 'shred-0001')
	landed := store_erase_doc_local(mut ms, hash, tomb)
	assert landed, 'first erase must land'
	store_cxpack_flush(mut ms) or { panic('flush: ${err.msg()}') }
	return tomb
}

fn test_erase_records_tombstone_and_survives_reopen() {
	root := se_root('reopen')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms := se_new(root)
	keep := se_put(mut ms, '[keep [k 1]]')
	doomed := se_put(mut ms, '[order [customer "o-5521"]]')
	former_root := (ms.obj_roots[doomed] or { panic('root') }).hex()
	tomb := se_erase(mut ms, doomed)

	// live state: entry destroyed, tombstone recorded, root indexed
	assert !store_doc_present(ms, doomed)
	assert store_doc_present(ms, keep)
	assert (ms.erased[doomed] or { '' }) == tomb
	assert (ms.erased_roots[former_root] or { '' }) == doomed

	// the lineage records the act: kind=erase, docs plane, dense position
	last := ms.advances.last()
	assert last.plane == 'docs'
	assert last.kind == 'erase'
	assert last.hash == doomed

	// the act — and its attribution — survive a reopen
	mut ms2 := se_new(root)
	store_cxpack_load(mut ms2) or { panic('reopen: ${err.msg()}') }
	assert !store_doc_present(ms2, doomed)
	assert (ms2.erased[doomed] or { '' }) == tomb
	assert (ms2.erased_roots[former_root] or { '' }) == doomed
	// the reopen's seed compacts the erase into the lineage (from-empty
	// replay tells the honest story)
	store_feed_seed(mut ms2)
	mut seeded_erase := false
	for a in ms2.advances {
		if a.kind == 'erase' && a.hash == doomed {
			seeded_erase = true
		}
	}
	assert seeded_erase, 'seed must compact the erased tombstone into the lineage'
}

fn test_erase_survives_compaction() {
	root := se_root('compact')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms := se_new(root)
	se_put(mut ms, '[keep [k 2]]')
	doomed := se_put(mut ms, '[order [customer "o-9944"]]')
	tomb := se_erase(mut ms, doomed)
	// compaction folds T tombstones away — the E record must NOT fold
	// (attribution survives compaction, erasure_compliance §6)
	store_cxpack_compact(mut ms) or { panic('compact: ${err.msg()}') }
	manifest := os.read_file(os.join_path(root, cxpack_manifest)) or { panic('manifest') }
	assert manifest.contains('E\t${doomed}'), 'the E record must survive the compaction snapshot'
	assert !manifest.contains('T\t'), 'compacted snapshot carries no T tombstones'
	mut ms2 := se_new(root)
	store_cxpack_load(mut ms2) or { panic('reopen after compact: ${err.msg()}') }
	assert (ms2.erased[doomed] or { '' }) == tomb
}

fn test_reput_supersedes_tombstone() {
	root := se_root('reput')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms := se_new(root)
	doomed := se_put(mut ms, '[order [customer "o-1111"]]')
	se_erase(mut ms, doomed)
	assert doomed in ms.erased
	// a later put of the same content supersedes the tombstone (§7b.1:
	// erasure destroys what was held, it does not censor future acts)
	reput := se_put(mut ms, '[order [customer "o-1111"]]')
	assert reput == doomed
	assert store_doc_present(ms, doomed)
	assert doomed !in ms.erased
	// the supersede holds across a reopen (replay order decides: E then D)
	mut ms2 := se_new(root)
	store_cxpack_load(mut ms2) or { panic('reopen: ${err.msg()}') }
	assert store_doc_present(ms2, doomed)
	assert doomed !in ms2.erased
	// and a RE-erase after the re-put lands a fresh operative E record
	tomb2 := se_erase(mut ms2, doomed)
	mut ms3 := se_new(root)
	store_cxpack_load(mut ms3) or { panic('reopen 2: ${err.msg()}') }
	assert (ms3.erased[doomed] or { '' }) == tomb2
	assert !store_doc_present(ms3, doomed)
}

fn test_erase_absent_doc_converges_and_dedups() {
	root := se_root('absent')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms := se_new(root)
	se_put(mut ms, '[keep [k 3]]')
	ghost := 'sha2-256:' + '11'.repeat(32)
	tomb := store_erase_tombstone(ghost, []u8{}, '2026-08-07T12:00:00Z', 'did:key:replica',
		'', 'shred-0002')
	assert store_erase_doc_local(mut ms, ghost, tomb), 'erase-of-absent must record the tombstone'
	assert (ms.erased[ghost] or { '' }) == tomb
	// idempotent: the second act never lands (deduped, no second lineage act)
	acts_before := ms.advances.len
	assert !store_erase_doc_local(mut ms, ghost, tomb)
	assert ms.advances.len == acts_before, 're-erase must not append a second act'
}

fn test_erase_file_backend_index_roundtrip() {
	root := se_root('flat')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	mut ms := &MemStore{
		url:     'file://${root}'
		backend: 'file'
		root:    root
		is_open: true
	}
	doc := cx.parse('[order [customer "o-7777"]]') or { panic('parse') }
	c := render_canonical(doc.elements[0])
	h := cx.cx_text_hash(c) or { panic('hash') }
	store_put_canonical(mut ms, h, c) or { panic('put') }
	store_persist(mut ms) or { panic('persist: ${err.msg()}') }
	tomb := store_erase_tombstone(h, []u8{}, '2026-08-07T12:00:00Z', 'did:key:tester',
		'gdpr-17', 'shred-0003')
	assert store_erase_doc_local(mut ms, h, tomb)
	store_append(mut ms, store_tombstone_record(h) + store_erase_record(h, tomb)) or {
		panic('append: ${err.msg()}')
	}
	// replay: T removes the doc, E records the tombstone
	mut ms2 := &MemStore{
		url:     'file://${root}'
		backend: 'file'
		root:    root
		is_open: true
	}
	store_read_index(os.join_path(root, store_index_name), mut ms2) or { panic(err.msg()) }
	assert h !in ms2.docs
	assert (ms2.erased[h] or { '' }) == tomb
	// the snapshot writer keeps the E record (compaction-survival on file://)
	store_persist(mut ms2) or { panic('persist 2: ${err.msg()}') }
	mut ms3 := &MemStore{
		url:     'file://${root}'
		backend: 'file'
		root:    root
		is_open: true
	}
	store_read_index(os.join_path(root, store_index_name), mut ms3) or { panic(err.msg()) }
	assert (ms3.erased[h] or { '' }) == tomb
}

// #720 item 1 (erasure_compliance §6): the LOCAL get path must give the same
// three-way discriminator the §7b wire path already gives — never-existed
// (CXER1121) / corrupt (CXER1120) / lawfully erased (the attributed [erased]
// tombstone on the VALUE channel). Before the fix, a replayed local store
// answered CXER1121 for an erased doc — erasure indistinguishable from
// never-existed exactly where the audit trail matters.
fn test_local_get_doc_of_erased_answers_tombstone() {
	root := se_root('getdisc')
	os.rmdir_all(root) or {}
	defer {
		os.rmdir_all(root) or {}
	}
	caps_set_all() // file substrates gate on the write capability
	h := store_open_impl('file://${root}', '', '', false, true, map[string]string{})
	assert !is_err_value(h), 'open failed: ${render_canonical(h)}'
	doc := cx.parse('[patient [name "X"]]') or { panic('parse') }
	put := store_stdlib_builtin_inner('store-put-doc', [h, doc.elements[0]]) or {
		panic('put: ${err.msg()}')
	}
	assert !is_err_value(put), 'put must succeed: ${render_canonical(put)}'
	hash := (put as cx.ScalarNode).value as string
	mut ms, _, ok := store_get_open(h)
	assert ok
	tomb := store_erase_tombstone(hash, (ms.obj_roots[hash] or { []u8{} }).clone(),
		'2026-08-07T12:00:00Z', 'did:key:tester', 'gdpr-17', 'shred-0002')
	assert store_erase_doc_local(mut ms, hash, tomb)
	// get-doc: the typed tombstone VALUE, never the not-found fault.
	got := store_stdlib_builtin_inner('store-get-doc', [h, store_str(hash)]) or {
		panic('get: ${err.msg()}')
	}
	assert !is_err_value(got), 'erased must not answer a fault: ${render_canonical(got)}'
	assert got is cx.Element, 'want an element, got: ${render_canonical(got)}'
	assert (got as cx.Element).name == 'erased', 'want the [erased] tombstone, got: ${render_canonical(got)}'
	// get-doc-text: the tombstone canonical text VERBATIM (§7b wire parity).
	gt := store_stdlib_builtin_inner('store-get-doc-text', [h, store_str(hash)]) or {
		panic('get-text: ${err.msg()}')
	}
	assert gt is cx.ScalarNode, 'text form must be a scalar'
	assert (gt as cx.ScalarNode).value as string == tomb, 'text form must answer the tombstone verbatim'
	// a never-existed address stays the CXER1121 fault — the discriminator holds.
	miss := store_stdlib_builtin_inner('store-get-doc', [h,
		store_str('sha2-256:${'1'.repeat(64)}')]) or {
		panic('miss: ${err.msg()}')
	}
	assert is_err_value(miss), 'never-existed stays a fault'
	assert render_canonical(miss).contains('CXER1121'), 'never-existed stays not-found: ${render_canonical(miss)}'
	// exists: an erased doc is NOT present (erased ≠ present, §7b.1).
	ex := store_stdlib_builtin_inner('store-exists', [h, store_str(hash)]) or {
		panic('exists: ${err.msg()}')
	}
	assert ex is cx.ScalarNode, 'exists must answer a scalar'
	assert !((ex as cx.ScalarNode).value as bool), 'erased is not present'
}

// ── source: vcx/platform/store_erasure_transfer_guard_test.v ──
// R3.16's interim guard is GONE (stream 20 W4 landed the carriage it
// promised): store-migrate / store-clone now CARRY the erased-map — the
// attributed [erased …] tombstones ride the copy, so lawful-erasure
// attribution survives archival and a re-put of shredded content at the
// destination still supersedes a RECORDED tombstone, never a silent void.

fn etg_open(tag string) (cx.Node, &MemStore) {
	h := store_open_impl('mem://etg-${tag}', '', '', false, true, map[string]string{})
	ms, e, ok := store_get_open(h)
	if !ok {
		panic('open etg-${tag}: ${e}')
	}
	return h, ms
}

fn etg_put(mut ms MemStore, text string) string {
	doc := cx.parse(text) or { panic('parse') }
	c := cx.cx_text_canonical(text) or { panic('canonical') }
	_ = doc
	h := cx.cx_text_hash(c) or { panic('hash') }
	store_put_canonical(mut ms, h, c) or { panic('put: ${err.msg()}') }
	return h
}

fn test_migrate_carries_tombstones() {
	hf, mut from := etg_open('mig-src')
	ht, mut dstm := etg_open('mig-dst')
	h1 := etg_put(mut from, '[order id=1 total=9.5]')
	h2 := etg_put(mut from, '[order id=2 total=2.5]')
	// lawful shred through the ONE funnel — the E-record tombstone lands
	tomb := store_erase_tombstone(h2, []u8{}, '2026-08-07T12:00:00Z', 'did:key:tester',
		'gdpr-17', 'shred-etg-1')
	assert store_erase_doc_local(mut from, h2, tomb), 'erase must land'

	r := store_stdlib_builtin_inner('store-migrate', [hf, ht]) or {
		panic('store-migrate dispatch: ${err.msg()}')
	}
	rs := render_canonical(r)
	assert !is_err_value(r), 'migrate must carry the erased-map, got: ${rs}'
	assert h1 in dstm.obj_roots || h1 in dstm.docs, 'the live doc rides the copy'
	assert h2 in dstm.erased, 'the tombstone rides the copy'
	assert dstm.erased[h2] == tomb, 'the attribution survives verbatim'
}

fn test_clone_carries_tombstones() {
	hf, mut from := etg_open('cl-src')
	ht, mut dstc := etg_open('cl-dst')
	h1 := etg_put(mut from, '[order id=3 total=1.0]')
	tomb := store_erase_tombstone(h1, []u8{}, '2026-08-07T12:00:00Z', 'did:key:tester',
		'gdpr-17', 'shred-etg-2')
	assert store_erase_doc_local(mut from, h1, tomb), 'erase must land'

	r := store_stdlib_builtin_inner('store-clone', [hf, ht]) or {
		panic('store-clone dispatch: ${err.msg()}')
	}
	rs := render_canonical(r)
	assert !is_err_value(r), 'clone must carry the erased-map, got: ${rs}'
	assert h1 in dstc.erased, 'the tombstone rides the copy'
	assert dstc.erased[h1] == tomb, 'the attribution survives verbatim'
}

fn test_migrate_of_tombstone_free_source_still_works() {
	hf, mut from := etg_open('ok-src')
	ht, _ := etg_open('ok-dst')
	_ = etg_put(mut from, '[order id=4 total=7.0]')

	r := store_stdlib_builtin_inner('store-migrate', [hf, ht]) or {
		panic('store-migrate dispatch: ${err.msg()}')
	}
	rs := render_canonical(r)
	assert !is_err_value(r), 'tombstone-free migrate must succeed: ${rs}'
	assert rs.contains('doc-count=1') || rs.contains('doc-count'), 'migration report expected: ${rs}'
}
